    ///
    /// - Remark: HTTP `GET /finance/income_totals`.
    /// - Remark: Generated from `#/paths//finance/income_totals/get(getFinanceIncomeTotals)`.
    func getFinanceIncomeTotals(_ input: Operations.GetFinanceIncomeTotals.Input) async throws -> Operations.GetFinanceIncomeTotals.Output
    /// Get the authenticated user's supporter subscription
