    ///
    /// - Remark: HTTP `PUT /admin/supporter_tips`.
    /// - Remark: Generated from `#/paths//admin/supporter_tips/put(setSupporterTips)`.
    func setSupporterTips(_ input: Operations.SetSupporterTips.Input) async throws -> Operations.SetSupporterTips.Output
    /// List the supporter plans
    ///
    /// Every supporter plan, retired ones too, by rank. Needs the `manage_supporters` permission.
    ///
    /// - Remark: HTTP `GET /admin/supporter_plans`.
    /// - Remark: Generated from `#/paths//admin/supporter_plans/get(listAdminSupporterPlans)`.
    func listAdminSupporterPlans(_ input: Operations.ListAdminSupporterPlans.Input) async throws -> Operations.ListAdminSupporterPlans.Output
    /// Create a supporter plan
    ///
    /// Creates a supporter plan on a role, which then only the plan's subscriptions grant. The prices are made at the payment provider after the answer; the
    /// plan takes subscriptions once `prices_ready`. A plan that breaks a rule is a 422
    /// `/api/v1/problems/invalid-supporter-plan`, an unknown role a 404, and a server without a
    /// payment provider a 409 `/api/v1/problems/supporters-unavailable`. Recorded in the audit
    /// log. Needs the `manage_supporters` permission.
    ///
    ///
    /// - Remark: HTTP `POST /admin/supporter_plans`.
    /// - Remark: Generated from `#/paths//admin/supporter_plans/post(createSupporterPlan)`.
    func createSupporterPlan(_ input: Operations.CreateSupporterPlan.Input) async throws -> Operations.CreateSupporterPlan.Output
    /// Change a supporter plan
    ///
    /// Changes a supporter plan's terms and its role's permissions and position. New prices apply to new subscriptions and changes of plan only. A change that
    /// breaks a rule is a 422 `/api/v1/problems/invalid-supporter-plan`, a retired plan a 409
    /// `/api/v1/problems/supporter-plan-retired`, and an unknown plan a 404. Recorded in the
    /// audit log. Needs the `manage_supporters` permission.
    ///
    ///
    /// - Remark: HTTP `PATCH /admin/supporter_plans/{id}`.
    /// - Remark: Generated from `#/paths//admin/supporter_plans/{id}/patch(updateSupporterPlan)`.
    func updateSupporterPlan(_ input: Operations.UpdateSupporterPlan.Input) async throws -> Operations.UpdateSupporterPlan.Output
    /// Retire a supporter plan
    ///
    /// Retires a supporter plan for good: it takes no subscriptions any more, and
    /// every subscription of it ends at the end of its period (a pending one at once). A
    /// retired plan is a 409 `/api/v1/problems/supporter-plan-retired`, and an unknown one a
    /// 404. Recorded in the audit log. Needs the `manage_supporters` permission.
    ///
    ///
    /// - Remark: HTTP `POST /admin/supporter_plans/{id}/retire`.
    /// - Remark: Generated from `#/paths//admin/supporter_plans/{id}/retire/post(retireSupporterPlan)`.
    func retireSupporterPlan(_ input: Operations.RetireSupporterPlan.Input) async throws -> Operations.RetireSupporterPlan.Output
    /// List the subscriptions
    ///
    /// The subscriptions to the supporter plans, newest first, narrowed to a plan and a state.
    /// Needs the `manage_supporters` permission.
    ///
    ///
    /// - Remark: HTTP `GET /admin/supporter_subscriptions`.
    /// - Remark: Generated from `#/paths//admin/supporter_subscriptions/get(listSupporterSubscriptions)`.
    func listSupporterSubscriptions(_ input: Operations.ListSupporterSubscriptions.Input) async throws -> Operations.ListSupporterSubscriptions.Output
    /// Get a subscription
    ///
    /// One subscription to a supporter plan, as the list shows it. An unknown subscription is a 404.
    /// Needs the `manage_supporters` permission.
    ///
    ///
    /// - Remark: HTTP `GET /admin/supporter_subscriptions/{id}`.
    /// - Remark: Generated from `#/paths//admin/supporter_subscriptions/{id}/get(getSupporterSubscription)`.
    func getSupporterSubscription(_ input: Operations.GetSupporterSubscription.Input) async throws -> Operations.GetSupporterSubscription.Output
    /// End a subscription at once
    ///
    /// Ends a subscription at once, without a refund: the role goes now, and the
    /// payment provider stops billing. A refund is the operator's to make at the provider, except
    /// that a payment for a subscription still pending, which gave nothing, is refunded. A
    /// subscription that has ended is a 409 `/api/v1/problems/subscription-ended`, and an
    /// unknown one a 404. Recorded in the audit log. Needs the `manage_supporters` permission.
    ///
    ///
    /// - Remark: HTTP `POST /admin/supporter_subscriptions/{id}/end`.
    /// - Remark: Generated from `#/paths//admin/supporter_subscriptions/{id}/end/post(endSupporterSubscription)`.
    func endSupporterSubscription(_ input: Operations.EndSupporterSubscription.Input) async throws -> Operations.EndSupporterSubscription.Output
}

